CREATE OR REPLACE FUNCTION public.image_job_permanent_error(p_error text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT coalesce(p_error LIKE 'permanent:%' OR p_error ~* '(HTTP (400|401|402|403|404|405|413|422)|content_filter|safety|refusal|blocked)' OR p_error LIKE '%ai_consent_missing%' OR p_error ~ '(Image too large or empty|Image too large|Original image must use trusted storage|Unsupported original image format|Input buffer contains unsupported image format|Input buffer has corrupt header|source_removed_not_applied|stale_input_revision|sku_not_active)',false) $$;
CREATE OR REPLACE FUNCTION public.image_retry_delay(p_attempts integer,p_error text DEFAULT NULL) RETURNS interval LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT make_interval(secs=>greatest(CASE WHEN coalesce(p_error,'') ~ '(429|rate.?limit)' THEN 900 WHEN coalesce(p_attempts,0)>=5 THEN 900 ELSE 0 END,least(21600,30*power(2,least(10,greatest(0,coalesce(p_attempts,1)-1)))::int))) $$;
CREATE OR REPLACE FUNCTION public.handheld_listing_image_claim(p_limit integer DEFAULT 2) RETURNS SETOF public.inv_listing_image_jobs LANGUAGE plpgsql SET search_path='' AS $$
DECLARE c record; j public.inv_listing_image_jobs; s public.inv_skus; e text; slots int;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('listing-image-claim-cap',0));
 SELECT greatest(0,6-(SELECT count(*) FROM public.inv_listing_image_jobs WHERE status='processing' AND lease_until>now())-(SELECT count(*) FROM public.inv_product_content_image_jobs WHERE status='processing' AND lease_until>now())) INTO slots;
 IF slots=0 THEN RETURN; END IF;
 FOR c IN SELECT t.id,t.sku_id FROM (SELECT q.*,min(q.created_at) OVER(PARTITION BY q.sku_id) grp_at FROM public.inv_listing_image_jobs q WHERE (q.status IN('queued','retryable_failed') AND q.next_run_at<=now()) OR (q.status='processing' AND coalesce(q.lease_until,q.locked_at+interval '4 minutes','-infinity'::timestamptz)<=now())) t ORDER BY t.grp_at,t.sku_id,t.source_index,t.id LIMIT least(slots,greatest(1,least(coalesce(p_limit,2),6))) LOOP
 SELECT * INTO s FROM public.inv_skus WHERE id=c.sku_id FOR UPDATE SKIP LOCKED; IF NOT FOUND THEN CONTINUE; END IF;
 SELECT * INTO j FROM public.inv_listing_image_jobs WHERE id=c.id AND ((status IN('queued','retryable_failed') AND next_run_at<=now()) OR (status='processing' AND coalesce(lease_until,locked_at+interval '4 minutes','-infinity'::timestamptz)<=now())) FOR UPDATE SKIP LOCKED; IF NOT FOUND THEN CONTINUE; END IF;
 IF j.status='processing' THEN UPDATE public.inv_listing_image_jobs SET status='retryable_failed',last_error='worker_lease_expired',next_run_at=now()+public.image_retry_delay(j.attempts,'worker_lease_expired'),claim_token=NULL,lease_until=NULL,locked_at=NULL,locked_by=NULL,updated_at=now() WHERE id=j.id; CONTINUE; END IF;
 e:=CASE WHEN s.status IS DISTINCT FROM 'active' THEN 'sku_not_active' WHEN NOT coalesce((j.source_bucket||'/'||j.source_path)=ANY(s.image_paths),false) THEN 'source_removed_not_applied' ELSE NULL END;
 IF e IS NOT NULL THEN UPDATE public.inv_listing_image_jobs SET status='permanent_failed',last_error=e,claim_token=NULL,lease_until=NULL,locked_at=NULL,locked_by=NULL,updated_at=now() WHERE id=j.id;
 ELSE UPDATE public.inv_listing_image_jobs SET status='processing',attempts=least(attempts::bigint+1,2147483647)::int,claim_token=gen_random_uuid(),lease_until=now()+interval '4 minutes',locked_at=now(),locked_by=NULL,updated_at=now() WHERE id=j.id RETURNING * INTO j; END IF;
 PERFORM public.handheld_listing_image_refresh_status(j.sku_id); IF e IS NULL THEN RETURN NEXT j; END IF;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.handheld_listing_image_finish(p_id uuid,p_claim_token uuid,p_target_path text,p_error text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE j public.inv_listing_image_jobs; s public.inv_skus; st text; e text; prefix text; rev int; applied boolean;
BEGIN
 SELECT * INTO j FROM public.inv_listing_image_jobs WHERE id=p_id; IF NOT FOUND THEN RETURN 'stale'; END IF;
 SELECT * INTO s FROM public.inv_skus WHERE id=j.sku_id FOR UPDATE; IF NOT FOUND THEN RETURN 'stale'; END IF;
 SELECT * INTO j FROM public.inv_listing_image_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.status<>'processing' OR p_claim_token IS NULL OR j.claim_token IS DISTINCT FROM p_claim_token OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN RETURN 'stale'; END IF;
 SELECT image_input_revision INTO rev FROM public.listing_readiness WHERE sku_id=j.sku_id;
 e:=CASE WHEN rev IS NOT NULL AND coalesce(j.readiness_revision,0)<rev THEN 'stale_input_revision' WHEN s.status IS DISTINCT FROM 'active' THEN 'sku_not_active' WHEN NOT coalesce((j.source_bucket||'/'||j.source_path)=ANY(s.image_paths),false) THEN 'source_removed_not_applied' ELSE NULL END;
 IF e IS NOT NULL THEN st:='permanent_failed'; ELSIF p_error IS NOT NULL THEN e:=left(p_error,1000); st:=CASE WHEN public.image_job_permanent_error(p_error) THEN 'permanent_failed' ELSE 'retryable_failed' END;
 ELSE prefix:='sku-listing/gallery/'||j.sku_id::text||'/'||j.id::text||'/'||p_claim_token::text;
 IF p_target_path IS NULL OR p_target_path NOT IN(prefix||'.png',prefix||'.jpg',prefix||'.webp') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sku-listing' AND name=substring(p_target_path FROM length('sku-listing/')+1)) THEN RAISE EXCEPTION 'invalid_listing_image_target'; END IF;
 PERFORM set_config('boomer.listing_image_apply','1',true); applied:=public.handheld_apply_listing_image_result(j.sku_id,j.source_bucket||'/'||j.source_path,p_target_path); PERFORM set_config('boomer.listing_image_apply','',true);
 IF applied THEN st:='succeeded'; ELSE st:='permanent_failed'; e:='source_removed_not_applied'; END IF; END IF;
 UPDATE public.inv_listing_image_jobs SET status=st,target_path=CASE WHEN st='succeeded' THEN substring(p_target_path FROM length('sku-listing/')+1) ELSE target_path END,last_error=e,lease_until=NULL,locked_at=NULL,locked_by=NULL,updated_at=now(),completed_at=CASE WHEN st='succeeded' THEN now() ELSE completed_at END,next_run_at=CASE WHEN st='retryable_failed' THEN now()+public.image_retry_delay(j.attempts,p_error) ELSE next_run_at END WHERE id=p_id;
 PERFORM public.handheld_listing_image_refresh_status(j.sku_id); RETURN st;
END $$;
CREATE OR REPLACE FUNCTION public.product_content_image_claim(p_limit integer) RETURNS SETOF public.inv_product_content_image_jobs LANGUAGE plpgsql SET search_path='' AS $$
DECLARE c record; j public.inv_product_content_image_jobs; s public.inv_skus; slots int;
BEGIN
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('listing-image-claim-cap',0));
 SELECT greatest(0,6-(SELECT count(*) FROM public.inv_listing_image_jobs WHERE status='processing' AND lease_until>now())-(SELECT count(*) FROM public.inv_product_content_image_jobs WHERE status='processing' AND lease_until>now())) INTO slots;
 IF slots=0 THEN RETURN; END IF;
 IF EXISTS(SELECT 1 FROM public.inv_listing_image_jobs WHERE status IN('queued','retryable_failed') AND next_run_at<=now()) THEN RETURN; END IF;
 FOR c IN SELECT id,sku_id FROM public.inv_product_content_image_jobs WHERE (status IN('queued','retryable_failed') AND next_run_at<=now()) OR (status='processing' AND coalesce(lease_until,'-infinity'::timestamptz)<=now()) ORDER BY created_at,id LIMIT least(slots,greatest(1,least(coalesce(p_limit,2),6))) LOOP
 SELECT * INTO s FROM public.inv_skus WHERE id=c.sku_id FOR UPDATE SKIP LOCKED; IF NOT FOUND THEN CONTINUE; END IF;
 SELECT * INTO j FROM public.inv_product_content_image_jobs WHERE id=c.id AND ((status IN('queued','retryable_failed') AND next_run_at<=now()) OR (status='processing' AND coalesce(lease_until,'-infinity'::timestamptz)<=now())) FOR UPDATE SKIP LOCKED; IF NOT FOUND THEN CONTINUE; END IF;
 IF j.status='processing' THEN UPDATE public.inv_product_content_image_jobs SET status='retryable_failed',lease_until=NULL,claim_token=NULL,next_run_at=now()+public.image_retry_delay(j.attempts,'worker_lease_expired'),last_error='worker_lease_expired',updated_at=now() WHERE id=j.id; CONTINUE; END IF;
 IF s.status IS DISTINCT FROM 'active' OR s.kind IS DISTINCT FROM 'single' OR NOT coalesce(s.is_custom_price,false) OR NOT EXISTS(SELECT 1 FROM public.inv_product_content p,LATERAL jsonb_array_elements(p.published_blocks) b WHERE p.sku_id=j.sku_id AND b->>'type'='image' AND b->>'id'=j.block_id AND b->>'storage_path'=j.source_path) THEN UPDATE public.inv_product_content_image_jobs SET status='cancelled',updated_at=now() WHERE id=j.id; CONTINUE; END IF;
 UPDATE public.inv_product_content_image_jobs SET status='processing',attempts=least(attempts::bigint+1,2147483647)::int,claim_token=gen_random_uuid(),lease_until=now()+interval '4 minutes',updated_at=now() WHERE id=j.id RETURNING * INTO j; RETURN NEXT j;
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION public.product_content_image_finish(p_id uuid,p_claim_token uuid,p_target_path text,p_error text) RETURNS text LANGUAGE plpgsql SET search_path='' AS $$
DECLARE j public.inv_product_content_image_jobs; s public.inv_skus; c public.inv_product_content; draft jsonb; published jsonb; st text; prefix text;
BEGIN
 SELECT * INTO j FROM public.inv_product_content_image_jobs WHERE id=p_id; IF NOT FOUND THEN RETURN 'stale'; END IF;
 SELECT * INTO s FROM public.inv_skus WHERE id=j.sku_id FOR UPDATE;
 SELECT * INTO j FROM public.inv_product_content_image_jobs WHERE id=p_id FOR UPDATE;
 IF NOT FOUND OR j.status<>'processing' OR p_claim_token IS NULL OR j.claim_token IS DISTINCT FROM p_claim_token OR j.lease_until IS NULL OR j.lease_until<=clock_timestamp() THEN RETURN 'stale'; END IF;
 SELECT * INTO c FROM public.inv_product_content WHERE sku_id=j.sku_id FOR UPDATE;
 IF NOT FOUND OR s.status IS DISTINCT FROM 'active' OR s.kind IS DISTINCT FROM 'single' OR NOT coalesce(s.is_custom_price,false) THEN st:='cancelled';
 ELSIF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.published_blocks) b WHERE b->>'type'='image' AND b->>'id'=j.block_id AND b->>'storage_path'=j.source_path) THEN st:='cancelled';
 ELSIF p_error IS NOT NULL THEN st:=CASE WHEN public.image_job_permanent_error(p_error) THEN 'permanent_failed' ELSE 'retryable_failed' END;
 ELSE prefix:='sku-listing/content/'||j.sku_id::text||'/'||j.id::text||'/'||p_claim_token::text;
 IF p_target_path IS NULL OR p_target_path NOT IN(prefix||'.png',prefix||'.jpg',prefix||'.webp') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sku-listing' AND name=substring(p_target_path FROM length('sku-listing/')+1)) THEN PERFORM public.handheld_item_fail('validation_error','Invalid optimized content image'); END IF;
 SELECT coalesce(jsonb_agg(CASE WHEN b->>'type'='image' AND b->>'id'=j.block_id AND b->>'storage_path'=j.source_path THEN jsonb_set(b,'{storage_path}',to_jsonb(p_target_path)) ELSE b END ORDER BY ord),'[]') INTO draft FROM jsonb_array_elements(c.draft_blocks) WITH ORDINALITY blocks(b,ord);
 SELECT coalesce(jsonb_agg(CASE WHEN b->>'type'='image' AND b->>'id'=j.block_id AND b->>'storage_path'=j.source_path THEN jsonb_set(b,'{storage_path}',to_jsonb(p_target_path)) ELSE b END ORDER BY ord),'[]') INTO published FROM jsonb_array_elements(c.published_blocks) WITH ORDINALITY blocks(b,ord);
 IF draft IS DISTINCT FROM c.draft_blocks OR published IS DISTINCT FROM c.published_blocks THEN UPDATE public.inv_product_content SET draft_blocks=draft,published_blocks=published,version=version+1,published_version=CASE WHEN published IS DISTINCT FROM c.published_blocks THEN version+1 ELSE published_version END,updated_at=now() WHERE sku_id=j.sku_id; st:='succeeded'; ELSE st:='cancelled'; END IF; END IF;
 UPDATE public.inv_product_content_image_jobs SET status=st,lease_until=NULL,target_path=CASE WHEN p_error IS NULL THEN p_target_path ELSE target_path END,last_error=left(p_error,1000),updated_at=now(),next_run_at=CASE WHEN st='retryable_failed' THEN now()+public.image_retry_delay(j.attempts,p_error) ELSE next_run_at END WHERE id=p_id; RETURN st;
END $$;
CREATE OR REPLACE FUNCTION public.listing_readiness_is_ready(p_sku uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT CASE WHEN s.is_custom_price AND coalesce(s.kind,'single')='single' AND coalesce(s.inventory_policy,'tracked')<>'unlimited' THEN coalesce((SELECT r.images_settled AND r.image_plan IS DISTINCT FROM 'raw_declined' AND r.recognition_status='succeeded' AND r.recognition_revision=r.input_revision AND r.image_status='succeeded' AND r.image_revision=r.input_revision AND r.content_status='succeeded' AND r.content_revision=r.input_revision AND cardinality(s.image_paths)>0 AND NOT public.listing_readiness_has_raw(s.image_paths)
 AND NOT EXISTS(SELECT 1 FROM unnest(s.image_paths) p WHERE NOT EXISTS(SELECT 1 FROM inv_listing_image_jobs j WHERE j.sku_id=p_sku AND j.status='succeeded' AND 'sku-listing/'||j.target_path=p))
 AND NOT EXISTS(SELECT 1 FROM unnest(s.image_paths) p WHERE NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='sku-listing' AND o.name=substring(p FROM length('sku-listing/')+1)))
 AND NOT EXISTS(SELECT 1 FROM inv_listing_image_jobs j WHERE j.sku_id=p_sku AND j.readiness_revision>=r.image_input_revision AND j.status<>'succeeded')
 AND listing_readiness_detail_images_state(p_sku)='succeeded'
 AND EXISTS(SELECT 1 FROM inv_product_content c WHERE c.sku_id=p_sku AND c.published_version IS NOT NULL AND jsonb_typeof(c.published_blocks)='array' AND jsonb_array_length(c.published_blocks)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(c.published_blocks) b WHERE b->>'type'='image' AND (b->>'storage_path' IS NULL OR b->>'storage_path' NOT LIKE 'sku-listing/%' OR NOT EXISTS(SELECT 1 FROM inv_product_content_image_jobs j WHERE j.sku_id=p_sku AND j.block_id=b->>'id' AND j.status='succeeded' AND j.target_path=b->>'storage_path') OR NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='sku-listing' AND o.name=substring(b->>'storage_path' FROM length('sku-listing/')+1))))) FROM listing_readiness r WHERE r.sku_id=p_sku),false)
 ELSE coalesce((SELECT r.images_settled AND r.recognition_status='succeeded' AND r.recognition_revision=r.input_revision AND r.image_status='succeeded' AND r.image_revision=r.input_revision AND r.content_status='succeeded' AND r.content_revision=r.input_revision AND listing_readiness_detail_images_state(p_sku)='succeeded' AND EXISTS(SELECT 1 FROM inv_product_content c WHERE c.sku_id=p_sku AND jsonb_typeof(c.published_blocks)='array' AND jsonb_array_length(c.published_blocks)>0) FROM listing_readiness r WHERE r.sku_id=p_sku),true) END FROM inv_skus s WHERE s.id=p_sku
$$;
CREATE OR REPLACE FUNCTION public.storefront_image_ready(p_sku uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT coalesce((SELECT CASE WHEN s.is_custom_price AND coalesce(s.kind,'single')='single' AND coalesce(s.inventory_policy,'tracked')<>'unlimited' THEN listing_readiness_is_ready(p_sku) ELSE true END FROM inv_skus s WHERE s.id=p_sku),false) $$;
CREATE OR REPLACE VIEW public.storefront_ready_listings WITH(security_barrier=true) AS SELECT l.* FROM public.commerce_listings l WHERE public.storefront_image_ready(l.sku_id);
REVOKE ALL ON public.storefront_ready_listings FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.storefront_ready_listings TO service_role;
CREATE OR REPLACE FUNCTION public.storefront_ready_skus(p_ids uuid[]) RETURNS TABLE(sku_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT s.id FROM inv_skus s WHERE s.id=ANY(p_ids) AND public.storefront_image_ready(s.id) $$;
CREATE OR REPLACE FUNCTION public.listing_readiness_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NEW.status='published' AND NOT coalesce(listing_readiness_is_ready(NEW.sku_id),false) THEN NEW.status:='hidden'; NEW.readiness_hold:=true; NEW.published_at:=NULL;
 ELSIF NEW.status='published' THEN NEW.readiness_hold:=false; NEW.published_at:=coalesce(NEW.published_at,now());
 ELSIF TG_OP='UPDATE' AND OLD.readiness_hold AND (NOT NEW.readiness_hold OR NEW.status IS DISTINCT FROM OLD.status) THEN NEW.readiness_hold:=false; NEW.published_at:=OLD.published_at;
 ELSIF NEW.readiness_hold THEN NEW.published_at:=NULL; END IF; RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.listing_readiness_apply_pending_display(p_listing uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE l commerce_listings; BEGIN
 SELECT * INTO l FROM commerce_listings WHERE id=p_listing FOR UPDATE; IF NOT FOUND OR l.pending_display IS NULL OR NOT coalesce(listing_readiness_is_ready(l.sku_id),false) THEN RETURN; END IF;
 PERFORM set_config('boomer.listing_display_apply','1',true); UPDATE commerce_listings SET image_paths=l.pending_display->'image_paths',cover_url=l.pending_display->>'cover_url',image_urls=l.pending_display->'image_urls',pending_display=NULL,updated_at=now() WHERE id=p_listing; PERFORM set_config('boomer.listing_display_apply','',true);
END $$;
CREATE OR REPLACE FUNCTION public.published_product_content(p_sku_id uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('version',c.published_version,'published_blocks',c.published_blocks,'auto_sources',CASE WHEN c.version=(c.auto_sources->>'version')::int THEN c.auto_sources->'sources' END) FROM public.inv_product_content c JOIN public.inv_skus s ON s.id=c.sku_id WHERE c.sku_id=p_sku_id AND c.published_version IS NOT NULL AND s.status='active' AND s.is_display AND s.is_custom_price AND s.kind='single' AND public.storefront_image_ready(s.id) AND EXISTS(SELECT 1 FROM public.commerce_listings l WHERE l.sku_id=c.sku_id AND l.status='published') $$;
CREATE OR REPLACE FUNCTION public.listing_readiness_refresh(p_sku uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r listing_readiness; s inv_skus; v_open int; v_failed int; v_total int; v_err text; v_detail text;
BEGIN
 SELECT * INTO r FROM listing_readiness WHERE sku_id=p_sku FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('status','legacy'); END IF; SELECT * INTO s FROM inv_skus WHERE id=p_sku; r.last_error:=NULL;
 IF coalesce(btrim(s.name),'')<>'' AND coalesce(btrim(s.category),'')<>'' THEN r.recognition_status:='succeeded'; ELSE r.recognition_status:='failed'; r.last_error:='missing_category'; END IF;
 IF r.image_plan='ai' AND r.image_ai_actor IS NOT NULL AND coalesce(r.image_ai_policy,'')<>'' THEN INSERT INTO inv_listing_image_jobs(sku_id,source_bucket,source_path,source_index,ai_actor_user_id,ai_policy_version,target_bucket,status,next_run_at,readiness_revision) SELECT p_sku,'sku-raw',substring(p FROM length('sku-raw/')+1),(o-1)::int,r.image_ai_actor,r.image_ai_policy,'sku-listing','queued',now(),r.input_revision FROM unnest(s.image_paths) WITH ORDINALITY t(p,o) WHERE p LIKE 'sku-raw/%' ON CONFLICT(sku_id,source_bucket,source_path) DO NOTHING; END IF;
 SELECT count(*) FILTER(WHERE status IN('queued','processing','retryable_failed')),count(*) FILTER(WHERE status='permanent_failed'),count(*),max(last_error) FILTER(WHERE status='permanent_failed') INTO v_open,v_failed,v_total,v_err FROM inv_listing_image_jobs WHERE sku_id=p_sku AND readiness_revision>=r.image_input_revision;
 IF v_total>0 THEN r.images_settled:=true; END IF;
 IF v_open>0 THEN r.image_status:='running'; ELSIF v_failed>0 THEN r.image_status:='failed'; r.last_error:=coalesce(r.last_error,'image_failed'); ELSIF NOT r.images_settled THEN r.image_status:='pending';
 ELSIF (r.image_plan='ai' OR (s.is_custom_price AND coalesce(s.kind,'single')='single' AND coalesce(s.inventory_policy,'tracked')<>'unlimited')) AND listing_readiness_has_raw(s.image_paths) THEN r.image_status:='failed'; r.last_error:=coalesce(r.last_error,'raw_unprocessed');
 ELSIF coalesce(array_length(s.image_paths,1),0)>0 OR s.image_url IS NOT NULL THEN r.image_status:='succeeded'; ELSE r.image_status:='failed'; r.last_error:=coalesce(r.last_error,'missing_images'); END IF;
 IF s.is_custom_price AND coalesce(s.kind,'single')='single' AND coalesce(s.inventory_policy,'tracked')<>'unlimited' AND r.image_plan='raw_declined' THEN r.image_status:='failed'; r.last_error:='ai_consent_missing'; END IF;
 IF s.is_custom_price AND coalesce(s.kind,'single')='single' AND coalesce(s.inventory_policy,'tracked')<>'unlimited' AND r.image_status='succeeded' AND EXISTS(SELECT 1 FROM unnest(s.image_paths) p WHERE NOT EXISTS(SELECT 1 FROM inv_listing_image_jobs j WHERE j.sku_id=p_sku AND j.status='succeeded' AND 'sku-listing/'||j.target_path=p)) THEN r.image_status:='failed'; r.last_error:='image_success_receipt_missing'; END IF;
 v_detail:=listing_readiness_detail_images_state(p_sku); IF v_detail='failed' THEN r.last_error:=coalesce(r.last_error,'detail_image_failed'); END IF;
 UPDATE listing_readiness SET recognition_status=r.recognition_status,recognition_revision=r.input_revision,image_status=r.image_status,image_revision=r.input_revision,images_settled=r.images_settled,last_error=r.last_error,updated_at=now() WHERE sku_id=p_sku;
 RETURN jsonb_build_object('status','ok','input_revision',r.input_revision,'recognition',r.recognition_status,'image',r.image_status,'image_plan',r.image_plan,'detail_images',v_detail,'content',r.content_status,'content_revision',r.content_revision,'released',listing_readiness_release(p_sku));
END $$;
CREATE OR REPLACE FUNCTION public.listing_readiness_retry(p_sku uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r listing_readiness; n int; d int; BEGIN
 PERFORM 1 FROM inv_skus WHERE id=p_sku FOR UPDATE; SELECT * INTO r FROM listing_readiness WHERE sku_id=p_sku FOR UPDATE; IF NOT FOUND THEN RETURN jsonb_build_object('status','legacy'); END IF;
 UPDATE inv_listing_image_jobs j SET status='retryable_failed',next_run_at=now()+image_retry_delay(j.attempts,j.last_error),claim_token=NULL,lease_until=NULL,locked_at=NULL,locked_by=NULL,updated_at=now() WHERE j.sku_id=p_sku AND j.status='permanent_failed' AND j.readiness_revision>=r.image_input_revision AND NOT image_job_permanent_error(j.last_error) AND j.ai_actor_user_id IS NOT NULL AND j.ai_policy_version='2026-10-09-v1' AND EXISTS(SELECT 1 FROM handheld_ai_consents a WHERE a.user_id=j.ai_actor_user_id AND a.policy_version=j.ai_policy_version AND a.allowed) AND EXISTS(SELECT 1 FROM inv_skus s WHERE s.id=p_sku AND s.status='active' AND j.source_bucket||'/'||j.source_path=ANY(s.image_paths)); GET DIAGNOSTICS n=ROW_COUNT;
 UPDATE inv_product_content_image_jobs j SET status='retryable_failed',next_run_at=now()+image_retry_delay(j.attempts,j.last_error),claim_token=NULL,lease_until=NULL,updated_at=now() WHERE j.sku_id=p_sku AND j.status='permanent_failed' AND NOT image_job_permanent_error(j.last_error) AND EXISTS(SELECT 1 FROM handheld_ai_consents a WHERE a.user_id=j.ai_actor_user_id AND a.policy_version=j.ai_policy_version AND a.allowed) AND EXISTS(SELECT 1 FROM inv_product_content c,LATERAL jsonb_array_elements(c.published_blocks) b WHERE c.sku_id=p_sku AND b->>'id'=j.block_id AND b->>'storage_path'=j.source_path); GET DIAGNOSTICS d=ROW_COUNT;
 RETURN jsonb_build_object('status','ok','requeued_images',n,'requeued_detail_images',d);
END $$;
CREATE OR REPLACE FUNCTION public.image_job_notify_failure() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE loc uuid; reason text; BEGIN
 IF NEW.status='permanent_failed' AND OLD.status IS DISTINCT FROM NEW.status AND NEW.ai_actor_user_id IS NOT NULL THEN
 reason:=CASE WHEN NEW.last_error LIKE '%ai_consent_missing%' THEN 'ai_consent_missing' WHEN image_job_permanent_error(NEW.last_error) THEN 'permanent_image_failure' ELSE 'image_retry_exhausted' END;
 SELECT location_id INTO loc FROM inv_stocks WHERE sku_id=NEW.sku_id AND qty>0 ORDER BY location_id LIMIT 1;
 PERFORM pg_advisory_xact_lock(hashtextextended('image-notify:'||NEW.id::text,0));
 IF NOT EXISTS(SELECT 1 FROM inv_handheld_notifications WHERE kind='system' AND ref_type='image_job' AND ref_id=NEW.id) THEN INSERT INTO inv_handheld_notifications(kind,title,payload,location_id,user_id,audience,ref_type,ref_id,action_status) VALUES('system','商品图片未完成，暂不展示',jsonb_build_object('sku_id',NEW.sku_id,'error_code',reason),loc,NEW.ai_actor_user_id,'user','image_job',NEW.id,'pending'); END IF;
 ELSIF NEW.status='succeeded' THEN UPDATE inv_handheld_notifications SET action_status='handled' WHERE kind='system' AND ref_type='image_job' AND ref_id=NEW.id; END IF; RETURN NEW;
END $$;
CREATE TRIGGER image_gallery_failure_notify AFTER UPDATE OF status ON public.inv_listing_image_jobs FOR EACH ROW EXECUTE FUNCTION public.image_job_notify_failure();
CREATE TRIGGER image_detail_failure_notify AFTER UPDATE OF status ON public.inv_product_content_image_jobs FOR EACH ROW EXECUTE FUNCTION public.image_job_notify_failure();
REVOKE ALL ON FUNCTION public.image_job_permanent_error(text),public.image_retry_delay(integer,text),public.storefront_image_ready(uuid),public.storefront_ready_skus(uuid[]),public.image_job_notify_failure(),public.listing_readiness_retry(uuid),public.listing_readiness_refresh(uuid),public.handheld_listing_image_claim(integer),public.handheld_listing_image_finish(uuid,uuid,text,text),public.product_content_image_claim(integer),public.product_content_image_finish(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.image_job_permanent_error(text),public.image_retry_delay(integer,text),public.storefront_image_ready(uuid),public.storefront_ready_skus(uuid[]),public.listing_readiness_retry(uuid),public.listing_readiness_refresh(uuid),public.handheld_listing_image_claim(integer),public.handheld_listing_image_finish(uuid,uuid,text,text),public.product_content_image_claim(integer),public.product_content_image_finish(uuid,uuid,text,text) TO service_role;